class Solution:
    def calculate(self, s: str) -> int:
        total = 0
        sign = 1
        signs = [1]
        i = 0
        while i < len(s):
            ch = s[i]
            if ch.isdigit():
                num = 0
                while i < len(s) and s[i].isdigit():
                    num = num * 10 + int(s[i])
                    i += 1
                total += sign * num
                continue
            if ch == "+":
                sign = signs[-1]
            elif ch == "-":
                sign = -signs[-1]
            elif ch == "(":
                signs.append(sign)
            elif ch == ")":
                signs.pop()
            i += 1
        return total

